import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

posts = data['records']

# Count posts per user and sum their scores
user_stats = {}
for post in posts:
    owner_id = post.get('OwnerUserId')
    if owner_id is not None:
        score = post.get('Score', 0)
        if owner_id not in user_stats:
            user_stats[owner_id] = {'count': 0, 'total_score': 0}
        user_stats[owner_id]['count'] += 1
        user_stats[owner_id]['total_score'] += score

# Filter users with more than 10 posts
users_over_10 = {uid: stats for uid, stats in user_stats.items() if stats['count'] > 10}

# Calculate average scores for these users
result = []
for uid, stats in users_over_10.items():
    avg_score = stats['total_score'] / stats['count']
    result.append({'UserId': uid, 'PostCount': stats['count'], 'AvgScore': avg_score})

# Sort by UserId for consistency
result.sort(key=lambda x: x['UserId'])

print(f"Users with more than 10 posts: {len(result)}")
for r in result[:10]:
    print(r)
if len(result) > 10:
    print(f"... and {len(result) - 10} more users")

